var mw = "https://www.mowan.lol";

function getCookie(k) {
    var java = this.java;
    var cookie = this.cookie;
    var cookieValue = String(cookie.getCookie(mw)) || String(java.getCookie(mw));
    var parts = cookieValue.split(";");
    for (var i = 0; i < parts.length; i++) {
        var part = parts[i].trim();
        var idx = part.indexOf(k + "=");
        if (idx === 0) {
            return part.substring(k.length + 1);
        }
    }
    return "";
}

function Api(url, method) {
    method = method || 'GET';
    var java = this.java;
    var XDeviceID = this.getCookie('X-Device-ID');
    var Authorization = this.getCookie('Authorization');
    if (typeof Authorization === 'string') {
        Authorization = Authorization.replace("%20", " ");
    } else {
        Authorization = String(Authorization).replace("%20", " ");
    }
    var options = {
        method: method,
        headers: JSON.stringify({
            'Authorization': Authorization,
            'X-Device-ID': XDeviceID,
            'Content-Type': 'application/json',
            'User-Agent': 'yuedu_app',
            'Referer': mw
        })
    };
    return mw + url + ',' + JSON.stringify(options);
}

function showPara(url) {
    var java = this.java;
    var cache = this.cache;
