    java.showBrowser(url, htmlContent, "window.java=java;", JSON.stringify(browserConfig));
}

function createBubble(number, url, bubble) {
    var num = number > 99 ? "99+" : number.toString();
    bubble = bubble.replace('$num', num);
    var encodedBubble = this.java.base64Encode(bubble);
    encodedBubble = 'data:image/svg+xml;base64,' + encodedBubble + ',{"click":"showPara(\'' + (mw + url) + '\' )","style":"text"}';
    return '<img src="' + encodedBubble + '">';
}

