function Content(res) {
    var evn = this.Env();
    var content = "";
    var text = res.data.paragraphs;
    if (!text) {
        return res.data.msg || "暂无数据，请稍后再试~";
    }
    var enabledPara = res.data.comment.enabled;
    var bubble = enabledPara ? res.data.comment.bubble.svg : "";
    var enabledChapter = res.data.comment.chapter_enabled;
    var chapterSvgs = enabledChapter ? res.data.comment.chapter_card.svg : "";

    var contents = [];
    for (var i = 0; i < text.length; i++) {
        var item = text[i];
        var html = "";
        if (item.comment_count > 0 && enabledPara && bubble != '' && evn == 1) {
            html = '<p>' + item.text + this.createBubble(item.comment_count, item.comment_url, bubble) + '</p>';
        } else if (item.comment_count > 0 && enabledPara && bubble != '' && evn == 3) {
            html = '<div rs-native>' + item.text + '<comment count="' + item.comment_count + '" onPress="java.showReadingBrowser(\'' + (mw + item.comment_url) + '\',\'段评\')"></div>';
        } else {
            html = item.text;
        }
        if (item.image) {
            if (typeof item.image === 'string') {
                html += '<img src="' + item.image + '">';
            } else if (Array.isArray(item.image)) {
                for (var j = 0; j < item.image.length; j++) {
                    html += '<img src="' + item.image[j] + '">';
                }
            }
        }

        contents.push(html);
    }

    content = contents.join("\n");

    if (enabledChapter && chapterSvgs != "" && evn == 1) {
        var chapterUrl = res.data.comment.chapter_card.url;
        content += '\n' + this.createChapter(chapterUrl, chapterSvgs);
    } else if (enabledChapter && chapterSvgs != "" && evn == 3) {
        var chapterUrl = res.data.comment.chapter_card.url;
        var enChapterSvgs = java.base64Encode(chapterSvgs);
        content += '<div rs-native><img onPress="java.showReadingBrowser(\'' + (mw + chapterUrl) + '\',\'本章说\')" src="data:image/svg+xml;base64,' + enChapterSvgs + '"></div>';
    }

    return content;
}
